		/** 
		 * Tests creating a new Gateway.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Gateway");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Gateway" );

			try {            
				Gateway entity = GatewayService.getGatewayInstance().createGateway( generateNewEntity() );
				thePrimaryKey = entity.getGatewayId();
				LOGGER.info( "-- Successfully created a Gateway with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Gateway. 
		 */
		public Gateway testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Gateway" );

			Gateway entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Gateway with primary key" );
			msg.append( thePrimaryKey );
			
			GatewayFetchOneSummary fetchOneSummary = new GatewayFetchOneSummary( thePrimaryKey );

			try {
				entity = GatewayService.getGatewayInstance().getGateway( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Gateway " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Gateway.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Gateway." );

			StringBuilder msg = new StringBuilder( "Failed to update a Gateway : " );        
			Gateway entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Gateway." );

				// for use later on...
				thePrimaryKey = entity.getGatewayId();

				GatewayService proxy = GatewayService.getGatewayInstance();            
				proxy.updateGateway( entity );   

				LOGGER.info( "-- Successfully saved Gateway - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Gateway.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Gateway." );

			try{
			    Gateway entity = testRead(); 
				GatewayService.getGatewayInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Gateway with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Gateway with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Gateways.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Gateways:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Gateway : " );        
			List<Gateway> collection  = null;

			try {
				// call the static get method on the GatewayService
				collection = GatewayService.getGatewayInstance().getAllGateway();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Gateway entity = null;            
					Iterator<Gateway> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getGatewayId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

